private void ApplyMinimapScrollZoom(int zoomInDirection)
{
    float step = (MaxMinimapSpan - MinMinimapSpan) / MinimapScrollNotchesFullRange;
    minimapWorldSpan = Mathf.Clamp(
        minimapWorldSpan - zoomInDirection * step,
        MinMinimapSpan,
        MaxMinimapSpan);
